import { components } from '../../components';

import type { BannerType, CategoryBlocGameType, Game } from '../../types';
import { Box } from '@mui/material';
import { PopularComponent } from '@/components/PopularComponent';
import { NewerGameComponent } from '@/components/NewerGameComponent';
import { CategoryGameComponent } from '@/components/CategorieGameComponent';
import { TourGuide } from '@/components/ui/TourGuide';
import { useEffect, useState } from 'react';
import { LocalStorageService } from '@/storages/local_storage_service';

type Props = {
  banners: BannerType[];
  newGames: Game[];
  popularGames: Game[];
  categories: CategoryBlocGameType[];
};

export const HomeDekstop: React.FC<Props> = ({
  banners,
  newGames,
  popularGames,
  categories,
}) => {
  const [alreadyVisited, setAlreadyVisited] = useState<boolean>(true);
  const renderHeader = () => {
    return (
      <components.Header
        showBasket={true}
        showBurger={false}
        showLogo={false}
      />
    );
  };

  const renderModal = () => {
    return <components.Modal />;
  };

  const renderModalSubscribe = () => {
    return <components.ModalSubscribe />;
  };

  useEffect(() => {
    // Vérifier si l'utilisateur a déjà visité le tour
    const timer = setTimeout(() => {
      const visited = LocalStorageService.isHomeDictacielTourVisited();
      setAlreadyVisited(visited);
      if (!visited) {
        // Si ce n'est pas le cas, marquer comme visité
        LocalStorageService.saveHomeDictacielTourVisited();
      }
    }, 300); // Appliquer un délai de 300ms

    return () => clearTimeout(timer);
  }, []);

  return (
    <Box component="section" style={{ padding: 0, margin: 0 }}>
      {renderHeader()}
      <PopularComponent popularGames={popularGames} />
      <NewerGameComponent newerGames={newGames} />
      {categories.map((category) => {
        if (category.games.length > 0) {
          return (
            <CategoryGameComponent
              key={category.categorieId}
              category={category}
            />
          );
        }
      })}
      {renderModal()}
      {renderModalSubscribe()}
      {!alreadyVisited && <TourGuide isDesktop={false} />}
    </Box>
  );
};
