'use client';

import React, { useEffect, useState } from 'react';
import { TabScreens } from '@/routes';
import { components } from '@/components';

import type { BannerType, CategoryBlocGameType, Game } from '../../types';
import { useDeviceDetect } from '@/hooks/useDeviceDetect';
import { HomePage } from './HomePage';
import { CategoriesPageClient } from '../categories/CategoriesPageClient';
import { Box, Grid, Stack } from '@mui/material';
import { svg } from '@/svg';
import { HomeTabSvg } from '@/svg/tabs/HomeTabSvg';
import { ProfileTabSvg } from '@/svg/tabs/ProfileTabSvg';
import { SearchTabSvg } from '@/svg/tabs/SearchTabSvg';
import { LocalStorageService } from '@/storages/local_storage_service';
import { ProfilePage } from '../profile/Profile';
import { useGameListPreload } from '@/hooks/useGamePreloader';
type Props = {
  banners: BannerType[];
  games: Game[];
  categories: CategoryBlocGameType[];
};

export const Home: React.FC<Props> = ({ banners, games, categories }) => {
  const { isDesktop } = useDeviceDetect();
  useGameListPreload(games);
  const pages = [
    <HomePage
      key={'homePage'}
      games={games}
      banners={banners}
      categories={categories}
    />,
    <CategoriesPageClient
      key={'CategoriePage'}
      games={games}
      categories={categories}
    />,
    <ProfilePage key={'ProfilPage'} />,
  ];
  const [currentMenu, setCurrentMenu] = useState<number>(0);

  const menu = [
    {
      id: TabScreens.HOME,
      name: TabScreens.HOME,
      icon: <HomeTabSvg active={currentMenu === 0} />,
    },
    {
      id: TabScreens.CATEGORIES,
      name: TabScreens.CATEGORIES,
      icon: <SearchTabSvg active={currentMenu === 1} />,
    },
    {
      id: TabScreens.PROFILE,
      name: TabScreens.PROFILE,
      icon: <ProfileTabSvg active={currentMenu === 2} />,
    },
  ];

  const onChangeMenu = (value: number) => {
    setCurrentMenu(value);
    LocalStorageService.saveCurrentNavigation(value);
  };

  const renderBottomTabBar = () => {
    return (
      <components.BottomTabBar
        onChange={onChangeMenu}
        currentActive={currentMenu}
      />
    );
  };

  const renderBackground = () => {
    return <components.Background />;
  };
  const renderSideBarMenu = () => {
    return (
      <Grid
        className="side-bar-menu"
        size={{ md: 2 }}
        style={{ padding: 0, margin: 0, height: '100vh' }}
      >
        <Stack
          direction="column"
          sx={{ padding: 0, margin: 0, width: '100%', height: '100%' }}
          alignItems={'center'}
          justifyContent="space-between"
        >
          <Box component="div" sx={{ my: 2, mx: 0, padding: 0, width: '100%' }}>
            {renderLogo()}
            {renderMenu()}
          </Box>
          <Box component="div" sx={{ my: 4, mx: 0, padding: 0, width: '100%' }}>
            {renderAllRight()}
          </Box>
        </Stack>
      </Grid>
    );
  };
  const renderLogo = () => {
    return (
      <Stack
        direction="row"
        sx={{ padding: 0, margin: 0, width: '100%' }}
        alignItems={'center'}
        justifyContent="center"
      >
        <svg.HeaderLogoSvg />
      </Stack>
    );
  };

  const renderAllRight = () => {
    return (
      <p className="t12" style={{ margin: 16 }}>
        Contenu Mentions légales Créateur du contenu @BoozTechnologies ©
        Copyright {new Date().getFullYear()} - Tous droits réservés
      </p>
    );
  };

  const renderMenu = () => {
    return (
      <components.SideBarMenu
        menuItems={menu}
        activeItem={currentMenu}
        onChangeMenu={onChangeMenu}
      />
    );
  };
  const renderContent = () => {
    return (
      <Grid
        size={{ md: 10 }}
        style={{ padding: 0, margin: 0, height: '100vh', overflow: 'auto' }}
      >
        {pages[currentMenu]}
      </Grid>
    );
  };

  useEffect(() => {
    setCurrentMenu(LocalStorageService.getCurrentNavigation());
  }, []);

  if (isDesktop) {
    return (
      <components.Screen>
        {renderBackground()}
        <Grid container spacing={0} style={{ padding: 0, margin: 0 }}>
          {renderSideBarMenu()}
          {renderContent()}
        </Grid>
      </components.Screen>
    );
  }

  return (
    <components.Screen>
      {renderBackground()}
      {pages[currentMenu]}
      {!isDesktop && renderBottomTabBar()}
    </components.Screen>
  );
};
