import React, { useEffect, useState } from 'react';
import { Box, Grid, Stack } from '@mui/material';
import { Routes } from '@/routes';
import { Game } from '@/types/GameType';
import { BlockHeading } from './BlockHeading';
import { items } from '@/items';
import YouTubePlayer from '@/components/player/video/youtube/YoutubePlayer';
import { URLS_ASSETS } from '@/config';
import { Button } from './Button';
import MaxLineText from './MaxLineText';
import { stores } from '@/stores';
import { useRouter } from 'next/navigation';
import { LocalStorageService } from '@/storages/local_storage_service';
import { useGameListPreload } from '@/hooks/useGamePreloader';
import { UserType } from '@/types/UserType';
import { hasActiveSubscription } from '@/utils/subscription_helper';
type Props = {
  popularGames: Game[];
};

export const PopularComponent: React.FC<Props> = ({ popularGames }) => {
  const router = useRouter();
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const popularGamesDisplay = popularGames.slice(0, 10);
  // useGameListPreload(popularGamesDisplay);
  const { openModal: openModalSubscribe } = stores.useModalSubscribe();
  const { user } = stores.useUserStore();

  useEffect(() => {
    const intervalId = setInterval(() => {
      setCurrentIndex((prevIndex) => {
        if (prevIndex < popularGamesDisplay.length - 1) {
          return prevIndex + 1;
        } else {
          return 0;
        }
      });
    }, 80000);

    return () => clearInterval(intervalId); // Nettoyer l'intervalle lors du démontage du composant
  }, [popularGamesDisplay.length]);

  const GameCardOverView = () => {
    return (
      <Box
        component="div"
        sx={{
          position: 'relative',
          width: '100%',
          height: '100%',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          alignItems: 'center',
          backgroundImage: `url("${URLS_ASSETS.GAMES}/${popularGamesDisplay[currentIndex]?.profilPicture}")`, // Utiliser l'URL de l'image
          backgroundSize: 'cover', // L'image couvre toute la zone
          backgroundPosition: 'center', // Centrer l'image
          borderRadius: 2,
        }}
      ></Box>
    );
  };

  const renderPlayButtonsDesktop = (game: Game) => {
    return (
      <Box
        component="div"
        sx={{
          width: '25%',
          marginTop: 2,
        }}
      >
        <Button
          label="Jouer maintenant"
          containerStyle={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'flex-end',
            flexDirection: 'row',
            width: '100%',
          }}
          style={{ padding: 0, margin: 0, height: 40 }}
          onClick={(e) => {
            e.stopPropagation();
            e.preventDefault();
            const url = `${Routes.GAME_PLAY}/${game?.title.replaceAll(' ', '_')}/${game?.id}`;
            if (user && hasActiveSubscription(user.subscriptions)) {
              router.push(url);
              return;
            }
            LocalStorageService.saveLocationRedirection(url);
            openModalSubscribe();

            // openModal();

            // addToCart(product);
          }}
        />
      </Box>
    );
  };

  return (
    <section
      id="popularGames"
      style={{
        marginBottom: 20,
        marginRight: 80,
      }}
    >
      <BlockHeading
        href={`${Routes.DETAILS_CATEGORY}/popular`}
        className="container"
        title="Top jeux"
        containerStyle={{ marginBottom: 14 }}
      />
      <Grid
        container
        spacing={2}
        sx={{
          padding: 2,
          backgroundColor: 'var(--accent-color-light)',
          borderRadius: 5,
          marginY: 2,
          marginLeft: 2,
          height: '55vh',
        }}
      >
        <Grid size={{ md: 8 }} sx={{ height: '100%', position: 'relative' }}>
          {popularGamesDisplay[currentIndex]?.videoCover ? (
            <Box
              component="div"
              sx={{
                position: 'absolute',
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                borderRadius: 5,
                overflow: 'hidden',
              }}
            >
              <YouTubePlayer
                videoId={
                  popularGamesDisplay[currentIndex].videoCover.split(
                    'v=',
                  )[1] as string
                }
                loop={true}
                autoPlay={true}
                muted={true}
                sx={{ width: '100%', height: '52vh', borderRadius: 5 }}
              />
              {/* Overlay qui bloque les interactions */}
              <Box
                component="div"
                sx={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  right: 0,
                  bottom: 0,
                  background:
                    'linear-gradient(to bottom, rgba(0, 0, 0, 0.25) 0%, rgba(0, 0, 0, 0.8) 100%)',
                  borderRadius: 5,
                  zIndex: 10,
                  cursor: 'default',
                }}
              >
                <Stack
                  direction="column"
                  className="swiper-games"
                  justifyContent="flex-end"
                  alignItems="flex-start"
                  sx={{
                    position: 'relative',
                    zIndex: 20,
                    width: '100%',
                    height: '100%',
                  }}
                >
                  <Box
                    component="div"
                    sx={{
                      padding: 2,
                      marginBottom: 2,
                      marginLeft: 2,
                      marginRight: 2,
                      width: 'fit-content',
                    }}
                  >
                    <h1 className="text-primary">
                      {popularGamesDisplay[currentIndex].title}
                    </h1>
                    <MaxLineText
                      text={popularGamesDisplay[currentIndex].description}
                      maxLines={4}
                    />
                    {renderPlayButtonsDesktop(
                      popularGamesDisplay[currentIndex],
                    )}
                  </Box>
                </Stack>
              </Box>
            </Box>
          ) : (
            <GameCardOverView />
          )}
        </Grid>
        <Grid size={{ md: 4 }} sx={{ height: '100%', overflowY: 'auto' }}>
          <ul className="container">
            {popularGamesDisplay.map((game, index, array) => {
              const isLast = index === array.length - 1;
              return (
                <Grid size={{ md: 12 }} key={game.id} sx={{ m: 0, p: 0 }}>
                  <items.GameItemRow
                    isLast={isLast}
                    key={game.id}
                    game={game}
                    border={currentIndex === index}
                  />
                </Grid>
              );
            })}
          </ul>
        </Grid>
      </Grid>
    </section>
  );
};
