  async preloadGame(gameUrl: string, gameId: string): Promise<void> {
    if (typeof window === 'undefined') return;

    if (this.preloadedGames.has(gameId)) {
      return;
    }

    this.preloadedGames.set(gameId, {
      status: 'loading',
      timestamp: Date.now(),
    });

    try {
      // UNIQUEMENT prefetch (méthode 1) - la plus sûre
      this.prefetchResources(gameUrl);

      // Marquer comme chargé
      this.preloadedGames.set(gameId, {
        status: 'loaded',
        timestamp: Date.now(),
      });
    } catch (error) {
      console.error(`❌ Erreur préchargement ${gameId}:`, error);
      this.preloadedGames.set(gameId, {
        status: 'error',
        timestamp: Date.now(),
      });
    }
  }

  /**
   * Méthode 1: Prefetch via <link> tags
   */
  private prefetchResources(gameUrl: string): void {
    if (typeof document === 'undefined') return;

    try {
      // Prefetch du HTML principal
      const linkPrefetch = document.createElement('link');
      linkPrefetch.rel = 'prefetch';
      linkPrefetch.href = gameUrl;
      linkPrefetch.as = 'document';
      document.head.appendChild(linkPrefetch);

      // Preconnect au domaine pour les futures requêtes
      const linkPreconnect = document.createElement('link');
      linkPreconnect.rel = 'preconnect';
      linkPreconnect.href = new URL(gameUrl).origin;
      linkPreconnect.crossOrigin = 'anonymous';
      document.head.appendChild(linkPreconnect);

      // DNS Prefetch pour résolution DNS anticipée
      const linkDnsPrefetch = document.createElement('link');
      linkDnsPrefetch.rel = 'dns-prefetch';
      linkDnsPrefetch.href = new URL(gameUrl).origin;
      document.head.appendChild(linkDnsPrefetch);

      // console.log(`🔗 Prefetch resources pour: ${gameUrl}`);
    } catch (error) {
      console.warn(`⚠️ Erreur prefetch resources:`, error);
    }
  }

  /**
   * Méthode 2: Fetch des ressources Unity critiques
   */
  private async fetchCriticalResources(
    gameUrl: string,
    gameId: string,
  ): Promise<void> {
    if (typeof fetch === 'undefined') return;

    try {
      const origin = new URL(gameUrl).origin;

      // Vérifier d'abord si l'origine est accessible
      try {
        const testResponse = await fetch(gameUrl, {
          method: 'HEAD',
          mode: 'no-cors', // ← Important pour éviter les erreurs CORS
        });
      } catch (error) {
        console.warn(`⚠️ Origine non accessible: ${origin}`);
        return; // Arrêter le préchargement pour ce jeu
      }

      const buildPath = `${origin}/Build`;

      // Liste des ressources Unity critiques par ordre de priorité
      const criticalFiles = [
        `${buildPath}/WEBGL.loader.js`, // 1. Loader (essentiel)
        `${buildPath}/WEBGL.framework.js.br`, // 2. Framework (Brotli)
        `${buildPath}/WEBGL.framework.js.gz`, // 3. Framework (Gzip)
        `${buildPath}/WEBGL.data.br`, // 4. Data (Brotli)
        `${buildPath}/WEBGL.data.gz`, // 5. Data (Gzip)
      ];

      // Fetch en parallèle des 3 premières ressources
      const fetchPromises = criticalFiles.slice(0, 3).map((url) =>
        fetch(url, {
          method: 'HEAD', // ← Utiliser HEAD au lieu de GET
          mode: 'no-cors',
          cache: 'force-cache',
        } as RequestInit)
          .then(async (response) => {
            if (response.ok) {
              const filename = url.split('/').pop();
              // console.log(`✅ Préchargé: ${filename}`);
              // Stocker en cache navigateur
              await response.blob();
              return true;
            }
            return false;
          })
          .catch((err) => {
            // const filename = url.split('/').pop();
            // console.log(`⚠️ Échec fetch ${filename}: ${err.message}`);
            return false;
          }),
      );

      // const results = await Promise.allSettled(fetchPromises);
      // const successCount = results.filter(r => r.status === 'fulfilled' && r.value).length;

      // console.log(`📦 ${successCount}/3 ressources critiques préchargées pour: ${gameId}`);
    } catch (error) {
      console.error(`❌ Erreur fetch resources pour ${gameId}:`, error);
    }
  }

