'use client';

import React, { useEffect } from 'react';
import dayjs from 'dayjs';

import type { BannerType, CategoryBlocGameType, Game } from '../../types';
import { useDeviceDetect } from '@/hooks/useDeviceDetect';
import { HomeMobile } from './HomeMobile';
import { HomeDekstop } from './HomeDesktop';

type Props = {
  banners: BannerType[];
  games: Game[];
  categories: CategoryBlocGameType[];
};

export const HomePage: React.FC<Props> = ({ banners, games, categories }) => {
  const { isDesktop } = useDeviceDetect();
  const now = dayjs();
  const sortedGames = [...games].sort((a, b) =>
    dayjs(b.created_at).isAfter(dayjs(a.created_at)) ? 1 : -1,
  );

  const recentGames = sortedGames.filter(
    (game) => now.diff(dayjs(game.created_at), 'month') < 3,
  );

  const newGames =
    recentGames.length > 0
      ? recentGames.slice(0, 10)
      : sortedGames.slice(0, 10);
  const popularGames = games
    .filter((game) => game.numberPlayed >= 0)
    .sort((a, b) => b.numberPlayed - a.numberPlayed)
    .slice(0, 10);

  useEffect(() => {
    document.body.style.backgroundColor = 'var(--white-color)';
  }, []);

  if (isDesktop) {
    return (
      <HomeDekstop
        popularGames={popularGames}
        newGames={newGames}
        categories={categories}
        banners={banners}
      />
    );
  }

  return (
    <HomeMobile
      popularGames={popularGames}
      newGames={newGames}
      categories={categories}
      banners={banners}
    />
  );
};
