'use client';

import React, { useEffect } from 'react';
import type { CategoryBlocGameType, Game } from '../../types';
import { useDeviceDetect } from '@/hooks/useDeviceDetect';
import { CategoriesDesktopPageClient } from './CategorieDesktop';
import { CategoriesMobilePageClient } from './CategorieMobile';
import { useGameListPreload } from '@/hooks/useGamePreloader';

type Props = {
  categories: CategoryBlocGameType[];
  games: Game[];
  isLoading?: boolean;
};

export const CategoriesPageClient: React.FC<Props> = ({
  categories,
  games,
  isLoading = false,
}) => {
  const { isDesktop } = useDeviceDetect();
  useGameListPreload(games);

  useEffect(() => {
    document.body.style.backgroundColor = 'var(--white-color)';

    return () => {
      // Cleanup si nécessaire
      document.body.style.backgroundColor = '';
    };
  }, []);

  if (isDesktop) {
    return (
      <CategoriesDesktopPageClient
        allGames={games}
        categories={categories}
        isLoading={isLoading}
      />
    );
  }

  return (
    <CategoriesMobilePageClient
      allGames={games}
      categories={categories}
      isLoading={isLoading}
    />
  );
};
