'use client';

import React, { useCallback, useMemo, useState } from 'react';
import { components } from '../../components';
import type { CategoryBlocGameType, Game } from '../../types';
import { Box } from '@mui/material';
import { items } from '@/items';

type Props = {
  categories: CategoryBlocGameType[];
  allGames: Game[];
  isLoading?: boolean;
};

export const CategoriesDesktopPageClient: React.FC<Props> = ({
  categories,
  allGames,
  isLoading = false,
}) => {
  const [searchGame, setSearchGame] = useState<string>('');

  // Mémoriser les résultats de recherche pour éviter les recalculs
  const gamesDisplay = useMemo(() => {
    if (!searchGame.trim()) return allGames;

    const searchLower = searchGame.toLowerCase();
    return allGames.filter((game) =>
      game.title.toLowerCase().includes(searchLower),
    );
  }, [searchGame, allGames]);

  // Handler optimisé avec useCallback
  const handleSearchChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      setSearchGame(e.target.value);
    },
    [],
  );

  const renderHeader = () => (
    <components.Header showBasket={true} showBurger={false} showLogo={false} />
  );

  const renderSearchInput = () => (
    <Box component="div" sx={{ marginX: 10 }}>
      <components.InputField
        inputType="text"
        placeholder="Rechercher un jeu par titre, catégorie ou éditeur"
        containerStyle={{ marginBottom: 16 }}
        onChange={handleSearchChange}
        value={searchGame}
      />
    </Box>
  );

  const renderCategories = () => {
    if (isLoading && categories.length === 0) {
      return (
        <Box sx={{ textAlign: 'center', padding: 4 }}>
          <p>Chargement des catégories...</p>
        </Box>
      );
    }

    return (
      <ul
        style={{
          display: 'grid',
          gap: 15,
          gridTemplateColumns: 'repeat(5, 1fr)',
        }}
      >
        {categories.map((category) => (
          <items.CategoryItem key={category.categorieId} category={category} />
        ))}
      </ul>
    );
  };

  const renderSearchResults = () => {
    if (gamesDisplay.length === 0) {
      return (
        <section>
          <h2 className="t16" style={{ marginBottom: 16 }}>
            Aucun résultat pour &quot;{searchGame}&quot;
          </h2>
        </section>
      );
    }

    return (
      <section>
        <h2 className="t16" style={{ marginBottom: 16 }}>
          {gamesDisplay.length} résultat{gamesDisplay.length > 1 ? 's' : ''}{' '}
          pour &quot;{searchGame}&quot;
        </h2>
        <ul
          style={{
            display: 'grid',
            gap: 15,
            gridTemplateColumns: 'repeat(6, 1fr)',
          }}
        >
          {gamesDisplay.map((game) => (
            <items.GameItem key={game.id} game={game} height={'20vh'} />
          ))}
        </ul>
      </section>
    );
  };

  const renderContent = () => (
    <main
      className="scrollable container"
      style={{ paddingTop: 15, paddingBottom: 20 }}
    >
      {renderSearchInput()}
      {searchGame.trim().length > 0
        ? renderSearchResults()
        : renderCategories()}
    </main>
  );

  return (
    <components.Screen>
      {renderHeader()}
      {renderContent()}
      <components.Modal />
      <components.ModalSubscribe />
    </components.Screen>
  );
};
