'use client';

import { useEffect, useState } from 'react';
import { Home } from './Home';
import { data } from '@/data';
import { Game } from '@/types/GameType';
import { getUniqueGames } from '@/utils/game_helper';
import {
  getAllCategoriesBlocGameIndexDb,
  getAllGamesIndexDb,
  saveAllGamesIndexDb,
  saveCategoriesBlocGameIndexDb,
} from '@/storages/indexed_db_service';
import { CategoryBlocGameType } from '@/types/CategoryBlocGameType';
import { useDeviceDetect } from '@/hooks/useDeviceDetect';
import { stores } from '@/stores';
import { sortNotifications } from '@/utils/notification_helper';
import { NotificationType } from '@/types/NotificationType';
import dayjs from 'dayjs';

export function HomePageClient() {
  const { isOnline } = useDeviceDetect();
  const [games, setGames] = useState<Game[]>([]);
  const [banners] = useState([]);
  const [categories, setCategories] = useState<CategoryBlocGameType[]>([]);
  const {
    init,
    setNotifications,
    clear: clearNotification,
  } = stores.useNotificationStore();
  const { init: initPricing, setPricings } = stores.usePricingStore();
  const { logout, setUser } = stores.useUserStore();
  // 1. Charger d'abord depuis indexDB
  async function loadGamesFromIndexDB() {
    try {
      const gamesFromDB = await getAllGamesIndexDb();
      if (gamesFromDB && gamesFromDB.length > 0) {
        setGames(gamesFromDB);
      }
      const categoriesBlocGamesFromDB = await getAllCategoriesBlocGameIndexDb();
      if (categoriesBlocGamesFromDB && categoriesBlocGamesFromDB.length > 0) {
        const categorieSlice = (
          categoriesBlocGamesFromDB as CategoryBlocGameType[]
        ).map((category) => {
          return {
            ...category,
            games: category.games
              .sort((a, b) =>
                dayjs(b.created_at).isAfter(dayjs(a.created_at)) ? 1 : -1,
              )
              .slice(0, 10), // Limiter à 10 jeux par catégorie
          };
        });
        setCategories(categorieSlice);
      }
      init();
      initPricing();
    } catch (error) {
      console.error(
        'Erreur lors du chargement des jeux depuis IndexDB:',
        error,
      );
    }
  }

  // 2. Charger ensuite depuis API pour mise à jour
  async function fetchData() {
    try {
      const [gamesData, userData, pricingData] = await Promise.all([
        data.getGames(),
        data.getUser(),
        data.getPricing(),
      ]);
      if (gamesData.length > 0) {
        const allGames = gamesData
          .map((gameWithCategorie) => gameWithCategorie.games)
          .flat();
        const allGameFilter = getUniqueGames(allGames);
        // Mettre à jour le state React
        setGames(allGameFilter);
        const categorieSlice = (gamesData as CategoryBlocGameType[]).map(
          (category) => {
            return {
              ...category,
              games: category.games
                .sort((a, b) =>
                  dayjs(b.created_at).isAfter(dayjs(a.created_at)) ? 1 : -1,
                )
                .slice(0, 10), // Limiter à 10 jeux par catégorie
            };
          },
        );

        setCategories(categorieSlice);
        // Mettre à jour dans l'indexDB
        await saveAllGamesIndexDb(allGameFilter);
        await saveCategoriesBlocGameIndexDb(
          gamesData as CategoryBlocGameType[],
        );
      }
      if (pricingData.length > 0) {
        const pricings = pricingData.sort((a, b) => a.price - b.price);
        setPricings(pricings);
      }
      if (userData) {
        const notifications = sortNotifications(
          userData.notifications as NotificationType[],
        );
        setNotifications(notifications);
        setUser(userData);
      } else {
        clearNotification();
        logout();
      }
    } catch (error) {
      console.error('Erreur lors du chargement des données depuis API:', error);
    }
  }

  useEffect(() => {
    loadGamesFromIndexDB();
    if (isOnline) {
      fetchData();
    }
  }, [isOnline]);

  return <Home banners={banners} games={games} categories={categories} />;
}
