'use client';

import Image from 'next/image';
import React, { useEffect, useRef, useState } from 'react';
import { useRouter } from 'next/navigation';
import { Swiper, SwiperSlide } from 'swiper/react';
import { Swiper as SwiperClass } from 'swiper';
import { Navigation } from 'swiper/modules';
import { items } from '../../items';
import { Routes } from '../../routes';
import { TourGuide } from '@/components/ui/TourGuide';
import type { BannerType, CategoryBlocGameType, Game } from '../../types';
import { URLS_ASSETS } from '@/config';
import { Box } from '@mui/material';
import { components } from '@/components';
import { LocalStorageService } from '@/storages/local_storage_service';
import { useGameListPreload } from '@/hooks/useGamePreloader';

type Props = {
  banners: BannerType[];
  newGames: Game[];
  popularGames: Game[];
  categories: CategoryBlocGameType[];
};

export const HomeMobile: React.FC<Props> = ({
  banners,
  newGames,
  popularGames,
  categories,
}) => {
  const router = useRouter();

  // Références et états pour la navigation des jeux populaires
  const swiperPopularRef = useRef<SwiperClass | null>(null);
  const prevPopularRef = useRef<HTMLDivElement>(null);
  const nextPopularRef = useRef<HTMLDivElement>(null);
  const [isPopularBeginning, setIsPopularBeginning] = useState<boolean>(true);
  const [isPopularEnd, setIsPopularEnd] = useState<boolean>(false);
  const [alreadyVisited, setAlreadyVisited] = useState<boolean>(true);

  useEffect(() => {
    document.body.style.backgroundColor = 'var(--white-color)';
  }, []);

  // Effect pour calculer l'état isEnd pour les jeux populaires
  useEffect(() => {
    const popularLength = popularGames.length;

    // Si on a 1.6 jeux ou moins visibles, pas besoin de navigation
    if (popularLength <= 2) {
      setIsPopularEnd(true);
    } else {
      setIsPopularEnd(false);
    }
  }, [popularGames.length]);

  // Effect pour initialiser la navigation des jeux populaires
  useEffect(() => {
    const timer = setTimeout(() => {
      if (
        swiperPopularRef.current &&
        !swiperPopularRef.current.destroyed &&
        prevPopularRef.current &&
        nextPopularRef.current
      ) {
        const swiper = swiperPopularRef.current;

        // Détruire l'ancienne navigation
        if (swiper.navigation) {
          swiper.navigation.destroy();
        }

        // Reconfigurer la navigation (merge pour ne pas écraser les classes
        // par défaut de Swiper comme disabledClass, sinon le prochain
        // navigation.destroy() plante sur `disabledClass.split is not a function`)
        if (
          typeof swiper.params.navigation === 'object' &&
          swiper.params.navigation
        ) {
          Object.assign(swiper.params.navigation, {
            prevEl: prevPopularRef.current,
            nextEl: nextPopularRef.current,
          });
        }

        // Réinitialiser la navigation
        swiper.navigation.init();
        swiper.navigation.update();
      }
    }, 100);

    return () => clearTimeout(timer);
  }, [popularGames]);

  useEffect(() => {
    // Vérifier si l'utilisateur a déjà visité le tour
    const timer = setTimeout(() => {
      const visited = LocalStorageService.isHomeDictacielTourVisited();
      setAlreadyVisited(visited);
      if (!visited) {
        // Si ce n'est pas le cas, marquer comme visité
        LocalStorageService.saveHomeDictacielTourVisited();
      }
    }, 300); // Appliquer un délai de 300ms

    return () => clearTimeout(timer);
  }, []);

  // Fonctions de navigation manuelles pour les jeux populaires
  const handlePopularPrevSlide = () => {
    if (swiperPopularRef.current && !swiperPopularRef.current.destroyed) {
      swiperPopularRef.current.slidePrev();
    }
  };

  const handlePopularNextSlide = () => {
    if (swiperPopularRef.current && !swiperPopularRef.current.destroyed) {
      swiperPopularRef.current.slideNext();
    }
  };

  const renderHeader = () => {
    return <components.Header showBasket={true} showLogo={true} />;
  };

  const renderPopularGames = () => {
    return (
      <section
        id="popularGames"
        className="swiper-games"
        style={{ marginBottom: 20 }}
      >
        <components.BlockHeading
          href={`${Routes.DETAILS_CATEGORY}/popular`}
          className="container"
          title="Top jeux"
          containerStyle={{ marginBottom: 14 }}
        />

        <div
          className="swiper-games__carousel"
          style={{ position: 'relative' }}
        >
          {!isPopularBeginning && (
            <div
              ref={prevPopularRef}
              className="swiper-nav-button prev"
              onClick={handlePopularPrevSlide}
              style={{ cursor: 'pointer', zIndex: 10 }}
            >
              ❮
            </div>
          )}
          {!isPopularEnd && (
            <div
              ref={nextPopularRef}
              className="swiper-nav-button next"
              onClick={handlePopularNextSlide}
              style={{ cursor: 'pointer', zIndex: 10 }}
            >
              ❯
            </div>
          )}

          <Swiper
            modules={[Navigation]}
            spaceBetween={14}
            slidesPerView={2}
            navigation={false} // Désactiver la navigation automatique au début
            onSwiper={(swiper) => {
              swiperPopularRef.current = swiper;

              // Mettre à jour les états initiaux
              setIsPopularBeginning(swiper.isBeginning);
              setIsPopularEnd(swiper.isEnd);

              // Configurer la navigation après l'initialisation
              setTimeout(() => {
                if (
                  !swiper.destroyed &&
                  prevPopularRef.current &&
                  nextPopularRef.current &&
                  typeof swiper.params.navigation === 'object' &&
                  swiper.params.navigation
                ) {
                  Object.assign(swiper.params.navigation, {
                    prevEl: prevPopularRef.current,
                    nextEl: nextPopularRef.current,
                  });
                  swiper.navigation.init();
                  swiper.navigation.update();
                }
              }, 0);
            }}
            onSlideChange={(swiper) => {
              setIsPopularBeginning(swiper.isBeginning);
              setIsPopularEnd(swiper.isEnd);
            }}
            style={{ padding: '0 20px' }}
            className="swiper-games__swiper"
          >
            {popularGames.map((game) => {
              return (
                <SwiperSlide key={game.id}>
                  <items.GameItem game={game} height={'22vh'} />
                </SwiperSlide>
              );
            })}
          </Swiper>
        </div>
      </section>
    );
  };

  const renderBanner_1 = () => {
    return (
      <section className="container" style={{ marginBottom: 20 }}>
        <Image
          src={`${URLS_ASSETS.GAMES}/${banners[0].image}`}
          alt="Banner"
          width={0}
          height={0}
          sizes="100vw"
          priority={true}
          style={{ width: '100%', height: 'auto', borderRadius: 20 }}
          onClick={() => router.push(`${Routes.SHOP}/all`)}
        />
      </section>
    );
  };

  const rendeNewGames = () => {
    return (
      <section id="newerGames" style={{ marginBottom: 50 }}>
        <components.BlockHeading
          href={`${Routes.DETAILS_CATEGORY}/new`}
          className="container"
          title="Nouveaux jeux"
          containerStyle={{ marginBottom: 14 }}
        />
        <ul className="container">
          {newGames.map((game, index, array) => {
            const isLast = index === array.length - 1;
            return (
              <items.GameItemRow isLast={isLast} key={game.id} game={game} />
            );
          })}
        </ul>
      </section>
    );
  };

  const renderContent = () => {
    return (
      <main
        className="scrollable"
        style={{ paddingTop: 20, height: '100%', paddingBottom: 20 }}
      >
        {renderPopularGames()}
        {banners.length > 0 && renderBanner_1()}
        {rendeNewGames()}
      </main>
    );
  };

  const renderModal = () => {
    return <components.Modal />;
  };
  const renderModalSubscribe = () => {
    return <components.ModalSubscribe />;
  };

  return (
    <Box component="div" className="scrollable" sx={{ padding: 0, margin: 0 }}>
      {renderHeader()}
      {renderContent()}
      {renderModal()}
      {renderModalSubscribe()}
      {!alreadyVisited && <TourGuide isDesktop={false} />}
    </Box>
  );
};
